import collections
import json
import sys

def walk(value):
    if isinstance(value, dict):
        if "type" in value:
            yield str(value["type"])
        for child in value.values():
            yield from walk(child)
    elif isinstance(value, list):
        for child in value:
            yield from walk(child)

print(dict(sorted(collections.Counter(walk(json.load(open(sys.argv[1], encoding="utf-8")))).items())))
